from donnees import C,E

CHAPITRES=[]
CHAPITRES.append(C(12,'L’énergie : transferts et conversions','Où va l’énergie d’une lampe ?',
['Distinguer source, forme, transfert et conversion.','Construire une chaîne et un bilan énergétiques simples.','Relier rayonnement, climat et choix de ressources.'],['Combustions, mouvement et lecture d’un schéma.'],[
('Nommer avec précision',r'Une source fournit de l’énergie à un système. Une forme décrit comment elle est stockée ou se manifeste : énergie chimique d’une pile, cinétique d’un objet en mouvement, potentielle liée à une position, thermique ou nucléaire. Le Soleil fournit un rayonnement ; une éolienne reçoit de l’énergie du vent. Le mot « électrique » qualifie notamment un transfert électrique dans une chaîne. Un dispositif convertit l’énergie sans la créer.','c12-chaine','Pour la lampe : transfert électrique entrant, transferts par rayonnement et thermiques sortants. Les flèches ne représentent pas de la matière.'),
('Transférer et convertir',r'Un transfert fait passer de l’énergie d’un système à un autre : électriquement, mécaniquement, thermiquement ou par rayonnement. Une conversion change la forme sous laquelle on décrit l’énergie dans le fonctionnement étudié. Un moteur électrique reçoit de l’énergie électriquement et met une charge en mouvement, tout en échauffant son environnement. Une chaîne nomme les systèmes et le type de chaque transfert.','',''),
('Un bilan qui tient compte de tout',r'L’énergie se conserve. Pour un système, la variation de l’énergie stockée correspond à l’énergie reçue moins l’énergie cédée. Si un convertisseur fonctionne sans variation de son stockage, l’énergie entrante égale la somme des énergies sortantes. Les « pertes » sont des transferts qui ne répondent pas à l’effet utile recherché ; elles ne constituent pas une disparition. L’énergie s’exprime en joules (J).','c12-terre','Bilan qualitatif Terre-atmosphère : rayonnement solaire reçu, part renvoyée et rayonnement thermique émis. Les flèches ne sont pas quantitatives.'),
('Ressources et climat',r'Le charbon, le pétrole et le gaz sont des ressources fossiles ; leur combustion émet du dioxyde de carbone. Une ressource renouvelable se renouvelle à une échelle compatible avec l’usage humain, sous conditions d’exploitation. « Renouvelable » ne signifie pas « sans impact ». Certains gaz à effet de serre absorbent et émettent du rayonnement infrarouge terrestre. Si la Terre reçoit plus d’énergie qu’elle n’en cède, son énergie stockée augmente, ce qui peut élever sa température moyenne.','','')],
r'Une lampe reçoit $100\unite J$ électriquement et cède $25\unite J$ par rayonnement utile dans un modèle sans stockage. Les autres transferts totalisent $100-25=75\unite J$. L’énergie totale se conserve, mais toute l’énergie reçue n’est pas transférée sous la forme utile à l’éclairage.',
r'\textbf{Mission.} Étudier une lampe scolaire, un petit moteur et une cellule photovoltaïque, sur documents ou matériel autorisé. Définir chaque système, repérer l’entrée et les sorties puis construire une chaîne. Chercher un indice d’un transfert moins visible, par exemple un échauffement mesuré avec une sonde. Ne pas toucher une pièce chaude. \textbf{À rendre :} chaîne légendée, effet utile choisi, limites et bilan chiffré seulement lorsque toutes les données nécessaires sont fournies.',
['Une source n’est pas la même chose qu’une forme d’énergie.','Un transfert relie deux systèmes ; une conversion décrit leur fonctionnement.','L’énergie totale se conserve lorsqu’on inclut tous les transferts et stockages.','Un transfert non utile ne fait pas disparaître l’énergie.','Le rayonnement permet un transfert à travers le vide.'],
r'« Le moteur fabrique de l’énergie. » Il convertit de l’énergie reçue ; la production usuelle d’électricité désigne une conversion et un transfert.',[
E('Identifier une source','Dans une lampe alimentée par une pile, quel système fournit l’énergie à la lampe ?@@Quelle énergie est stockée dans la pile avant utilisation ?','La pile, via le circuit.@@De l’énergie chimique.'),
E('Nommer une forme','Quelle forme associe-t-on au mouvement d’un vélo ?@@Et à un objet placé en hauteur dans le champ de pesanteur ?','L’énergie cinétique.@@Une énergie potentielle liée à sa position dans le système Terre-objet.'),
E('Une unité','Quelle est l’unité SI de l’énergie ?@@Le watt est-il une autre écriture du joule ?','Le joule, J.@@Non : le watt est une unité de puissance, étudiée au chapitre 17.'),
E('Une sortie moins visible','Une lampe éclaire et chauffe son environnement. Nommer deux transferts sortants.@@L’échauffement signifie-t-il une destruction d’énergie ?','Un transfert par rayonnement et des transferts thermiques.@@Non : l’énergie est transférée à l’environnement.'),
E('Renouvelable ou fossile','Classer vent et charbon.@@Renouvelable signifie-t-il sans conséquence environnementale ?','Le vent relève d’une ressource renouvelable ; le charbon d’une ressource fossile.@@Non : fabrication, usages et fin de vie peuvent avoir des impacts.'),
E('Un bilan de lampe',r'Une lampe reçoit $200\unite J$ et produit $60\unite J$ de transfert utile sans stockage. Calculer les autres transferts.@@Vérifier le bilan.',r'$200-60=140\unite J$.@@$60+140=200\unite J$ : le bilan est conservatif.',calculs=[('200-60',140)]),
E('Le moteur',r'Un moteur reçoit $500\unite J$, cède $350\unite J$ mécaniquement et $150\unite J$ thermiquement. Le bilan est-il cohérent sans stockage ?@@Quel effet utile peut-on choisir ?','Oui : 350 + 150 = 500 J.@@La mise en mouvement d’une charge, si tel est l’objectif du dispositif.',calculs=[('350+150',500)]),
E('Un stockage augmente',r'Un système reçoit $80\unite J$ et en cède $30\unite J$. Quelle variation de stockage ?@@Peut-on imposer entrée égale sortie ici ?',r'Le stockage augmente de $80-30=50\unite J$.@@Non : cette égalité ne convient que lorsque le stockage ne varie pas.',calculs=[('80-30',50)]),
E('Une cellule photovoltaïque','Décrire l’entrée et une sortie utile d’une cellule photovoltaïque.@@La lumière transporte-t-elle seulement de l’information ?','Elle reçoit de l’énergie par rayonnement et peut en transférer électriquement à un circuit.@@Non : un rayonnement transporte aussi de l’énergie.'),
E('Un bilan terrestre','Sur une période, la Terre reçoit plus d’énergie qu’elle n’en cède. Que devient son stockage ?@@Pourquoi un simple dessin ne donne-t-il pas une valeur chiffrée ?','Son énergie stockée augmente.@@Il faut connaître les valeurs et le périmètre des transferts ; des flèches qualitatives ne sont pas des mesures.'),
E('Comparer deux lampes',r'Pour un même éclairage, A reçoit $100\unite J$ et B $40\unite J$ sur la même durée. Calculer l’économie avec B.@@Que faut-il vérifier pour que la comparaison soit équitable ?',r'$100-40=60\unite J$, soit 60 % de l’énergie de A.@@L’éclairage utile, la durée et le périmètre de comparaison doivent être comparables.',calculs=[('100-40',60)]),
E('Une énergie cinétique fournie',r'Pour préparer la 3e, on donne $E_c=\frac12mv^2$. Avec $m=2\unite{kg}$ et $v=3\unite{m/s}$, calculer $E_c$.@@Si la vitesse double, l’énergie double-t-elle ?',r'$E_c=\frac12\times2\times3^2=9\unite J$.@@Non : avec $v=6\unite{m/s}$, on obtient $36\unite J$, soit quatre fois plus. La formule est fournie et constitue un approfondissement.',calculs=[('.5*2*3**2',9),('.5*2*6**2',36)]),
E('Le mot « perte »','Pourquoi les pertes d’un moteur peuvent-elles rester importantes malgré la conservation de l’énergie ?@@Peut-on récupérer toute énergie aussi facilement ?','Les transferts thermiques vers l’environnement conservent l’énergie, mais ne répondent pas au but de mise en mouvement.@@Non : les formes et conditions de transfert ne sont pas également utilisables ; récupérer une énergie dispersée peut être difficile.'),
E('Un raccourci sur le climat','« Les gaz à effet de serre empêchent toute énergie de sortir. » Corriger.@@Quelle idée de bilan faut-il retenir ?','Ils absorbent et émettent une partie du rayonnement infrarouge ; ils ne bloquent pas toute sortie d’énergie.@@Il faut comparer l’ensemble des transferts entrants et sortants pour le système Terre-atmosphère.'),
E('Une comparaison incomplète','Un appareil émet peu de CO2 pendant son usage. Peut-on en déduire qu’il n’a aucun impact ?@@Quels postes ajouter ?','Non : l’usage n’est qu’une partie du cycle de vie.@@Extraction des matériaux, fabrication, transport, énergie fournie, durée de vie, réparabilité et traitement final.')],
E('Le convertisseur mystérieux',r'Un appareil reçoit $800\unite J$, cède $500\unite J$ mécaniquement et $220\unite J$ thermiquement. Calculer la variation d’énergie stockée.@@Un élève affirme qu’il a « perdu 80 J ». Corriger.@@Comment tester l’hypothèse d’un stockage plutôt qu’un transfert oublié ?',r'$800-500-220=80\unite J$ stockés en plus, si les transferts indiqués sont complets.@@L’énergie n’a pas disparu ; le système a pu stocker 80 J ou un transfert a été oublié.@@Examiner un échauffement interne, l’évolution du fonctionnement et les autres sorties ; le seul écart de bilan ne prouve pas un mécanisme.',calculs=[('800-500-220',80)])))

CHAPITRES.append(C(13,'Circuits : schématiser et protéger','Deux lampes peuvent-elles fonctionner indépendamment ?',
['Réaliser un schéma avec les symboles usuels.','Distinguer série, dérivation, branche et nœud.','Expliquer le risque d’un court-circuit et le rôle d’une protection.'],['Boucle fermée, conducteur et isolant.'],[
('Un modèle du circuit',r'Un générateur alimente un circuit ; des récepteurs convertissent l’énergie reçue. Pour un courant continu conventionnel, on représente le sens du courant de la borne positive vers la borne négative du générateur dans le circuit extérieur. Un interrupteur ouvert interrompt une branche. Les fils sont tracés avec une règle et les symboles ne représentent pas l’apparence photographique des objets.','c13-circuits','À gauche : deux lampes en série. À droite : deux branches en dérivation sur le même générateur.'),
('Série et dérivation',r'Deux dipôles sont en série lorsque le même courant les traverse dans une branche sans séparation entre eux. En dérivation, ils sont reliés aux mêmes deux nœuds et appartiennent à des branches différentes. Une branche est une portion entre deux nœuds ; un nœud relie au moins trois fils dans le modèle scolaire. Croiser des traits sans point de connexion ne signifie pas toujours les relier : la convention du schéma doit être lisible.','',''),
('Le court-circuit',r'Un fil de très faible résistance reliant directement les bornes d’un dipôle le court-circuite. Court-circuiter un générateur peut entraîner un courant très élevé, un échauffement et une détérioration. Même une pile peut chauffer dangereusement. On étudie le défaut sur schéma ou avec un matériel protégé sous conduite du professeur, jamais en reliant volontairement les bornes d’une pile par un fil.','c13-protection','Schéma de principe : une protection ouvre le circuit en cas de surintensité. Ce dessin n’est pas un plan de câblage du secteur.'),
('Des protections complémentaires',r'Un fusible ou un disjoncteur approprié peut interrompre une surintensité. L’isolation, la mise à la terre et la protection différentielle répondent à d’autres fonctions complémentaires dans une installation réelle. Pour les expériences du livre, utiliser exclusivement le matériel scolaire de très basse tension autorisé. Aucun montage n’est réalisé sur une prise domestique, même à partir d’un schéma simplifié.','','')],
r'Deux lampes sont branchées sur deux branches distinctes entre les bornes du générateur. Ouvrir l’interrupteur placé uniquement dans la branche de la première coupe ce trajet ; l’autre peut rester alimentée si son circuit est intact. En série, un interrupteur qui ouvre l’unique boucle coupe le courant dans les deux lampes.',
r'\textbf{Cahier des charges.} Réaliser avec le matériel scolaire deux lampes dont l’une peut être commandée sans interrompre l’autre. Dessiner le schéma avant de brancher. Faire vérifier le choix de la tension et les connexions par le professeur. Tester les deux états de l’interrupteur et comparer au schéma. \textbf{À rendre :} nœuds, branches, interrupteur et explication du trajet du courant. Les défauts dangereux sont analysés sur documents, sans les produire.',
['Un schéma utilise des symboles et des connexions explicites.','Un courant nécessite un trajet conducteur fermé dans les conditions étudiées.','En dérivation, les dipôles sont reliés aux mêmes deux nœuds.','Un court-circuit peut provoquer une surintensité.','Les expériences utilisent une alimentation scolaire autorisée.'],
r'Deux dessins qui se ressemblent géométriquement ne décrivent pas forcément le même circuit : suivre les connexions, pas la position des symboles.',[
E('Une boucle','Un interrupteur ouvert dans l’unique boucle permet-il un courant permanent ?@@Quel est le rôle du générateur ?','Non, dans le circuit simple étudié.@@Il fournit de l’énergie au circuit.'),
E('Le sens conventionnel','Dans le circuit extérieur alimenté en courant continu, de quelle borne part la flèche du courant ?@@Vers quelle borne revient-elle ?','De la borne positive du générateur.@@Vers la borne négative, par le trajet extérieur fermé.'),
E('En série','Deux lampes sont dans une seule boucle sans dérivation. Comment sont-elles associées ?@@Que produit l’ouverture d’un interrupteur de cette boucle ?','Elles sont en série.@@Elle interrompt le courant dans les deux lampes.'),
E('En dérivation','Deux lampes sont reliées aux mêmes deux nœuds. Quelle association ?@@Peuvent-elles appartenir à deux branches différentes ?','Une association en dérivation.@@Oui ; c’est précisément le cas du montage étudié.'),
E('La protection','Quel défaut peut provoquer une forte surintensité ?@@Un fusible intact est-il censé laisser passer indéfiniment toute intensité ?','Un court-circuit, notamment aux bornes du générateur.@@Non : il doit interrompre le circuit lorsqu’un dépassement approprié se produit, selon ses caractéristiques.'),
E('Compter les branches','Un générateur et deux lampes sont chacun reliés entre les mêmes deux nœuds. Combien de branches principales au total ?@@Combien contiennent une lampe ?','Trois branches : générateur, lampe 1, lampe 2.@@Deux branches contiennent chacune une lampe.'),
E('Placer l’interrupteur','Où placer un interrupteur pour commander seulement la lampe 1 d’un montage en dérivation ?@@Où le placer pour commander les deux ?','Dans la branche de la lampe 1, en série avec elle.@@Sur un trajet commun entre le générateur et le point de séparation, ou dans sa branche, selon le schéma.'),
E('Une lampe dévissée','Dans le modèle de deux lampes en dérivation, dévisser L1 ouvre sa branche. Que devient L2 ?@@Quelle hypothèse faut-il annoncer ?','L2 peut continuer de fonctionner.@@Le générateur reste adapté, l’autre branche intacte et l’ouverture ne coupe pas une connexion commune.'),
E('Suivre les connexions','Deux schémas présentent les mêmes dipôles à des endroits différents. Comment savoir s’ils sont équivalents ?@@La forme rectangulaire du dessin suffit-elle ?','Comparer les nœuds et les dipôles reliés à chaque paire de nœuds.@@Non : la topologie des connexions compte, pas l’apparence du tracé.'),
E('Un fil parasite','Un fil relie les bornes d’une lampe. Comment nommer ce défaut ?@@Que peut-il provoquer dans une boucle série ?','Il court-circuite la lampe.@@Le courant peut la contourner ; la répartition des tensions et l’intensité peuvent changer. L’effet dépend du reste du circuit.'),
E('Un cahier des charges','Proposer l’association de deux lampes pour qu’une panne par ouverture de l’une n’interrompe pas l’autre.@@Cette association garantit-elle contre tous les défauts ?','Les placer en dérivation sur des branches séparées, avec une alimentation adaptée.@@Non : un défaut commun au générateur, aux fils partagés ou aux protections peut couper tout le circuit.'),
E('Un défaut à ne pas tester','Pourquoi ne faut-il pas vérifier un court-circuit en reliant une pile par un fil ?@@Quelle alternative pédagogique convient ?','Le courant et l’échauffement peuvent devenir dangereux et endommager la pile.@@Analyser un schéma ou un dispositif scolaire protégé conduit par le professeur.'),
E('Une protection et sa limite','Un disjoncteur s’est ouvert. Peut-on le réarmer sans rechercher la cause ?@@Pourquoi une protection ne remplace-t-elle pas l’isolation ?','Il faut suivre les consignes de sécurité et faire examiner le défaut par une personne compétente ; l’élève ne manipule pas l’installation.@@Les protections ont des fonctions et des conditions de déclenchement différentes ; elles ne suppriment pas toute possibilité de contact dangereux.'),
E('Une autonomie trompeuse','Deux lampes en dérivation brillent, puis s’éteignent ensemble quand on retire un fil commun. Cela contredit-il le fonctionnement indépendant des branches ?@@Que fallait-il préciser ?','Non : le trajet partagé a été interrompu.@@L’indépendance concerne l’ouverture d’une branche réceptrice, avec générateur et connexions communes conservés.'),
E('Relier explication et schéma','Un élève dessine deux lampes en parallèle mais affirme qu’un seul courant les traverse successivement. Identifier l’incohérence.@@Comment la corriger ?','Sa description correspond à une série, pas au schéma en dérivation.@@Décrire la séparation du courant aux nœuds et les deux trajets récepteurs, ou redessiner une véritable association en série.')],
E('L’éclairage du refuge','Le cahier des charges impose deux lampes : L1 fonctionne lorsque l’alimentation est active ; L2 dépend d’un interrupteur. Décrire un schéma.@@Que se passe-t-il si l’interrupteur de L2 s’ouvre ?@@Où se situe un défaut qui éteint malgré tout les deux lampes ?','Relier chaque lampe à une branche entre les bornes du générateur ; placer l’interrupteur en série avec L2 seulement.@@Seule la branche L2 est ouverte ; L1 reste alimentée dans le modèle.@@Un fil commun coupé, le générateur ou une protection commune peuvent interrompre tout le montage.')))

CHAPITRES.append(C(14,'Mesurer l’intensité du courant','Le courant est-il consommé par une lampe ?',
['Brancher un ampèremètre en série et lire son calibre.','Appliquer l’unicité en série et l’additivité aux nœuds.','Argumenter à partir de mesures et de leur précision.'],['Circuits en série et en dérivation.'],[
('Une grandeur, une unité',r'L’intensité $I$ caractérise le courant électrique ; son unité est l’ampère (A). On utilise souvent le milliampère : $1\unite A=1\,000\unite{mA}$. Une lampe ne « consomme » pas le courant : elle reçoit de l’énergie transférée électriquement et la convertit. L’intensité et l’énergie ne sont pas la même grandeur.','c14-amperemetre','L’ampèremètre est inséré dans la branche ; les charges doivent traverser l’appareil, qui ne se branche jamais directement aux bornes du générateur.'),
('Insérer l’ampèremètre',r'Ouvrir le circuit hors alimentation, puis insérer l’appareil en série. Choisir la fonction courant continu et les bornes prescrites ; commencer avec un calibre adapté élevé puis affiner si possible. Le courant conventionnel entre par la borne A ou mA et sort par COM pour une lecture positive. Un signe négatif indique le sens de branchement dans le modèle, pas une intensité physiquement « impossible ».','',''),
('Une même intensité en série',r'Dans un circuit à une seule branche de dipôles en série, l’intensité est la même en tout point en régime établi. Pour deux lampes : $I_1=I_2=I_G$. Déplacer correctement l’ampèremètre permet de tester cette loi. Ajouter un dipôle peut modifier la valeur du courant dans toute la boucle ; cela ne contredit pas l’unicité à un instant donné.','c14-noeud','Au nœud, la somme des intensités entrantes égale celle des intensités sortantes. Les flèches fixent les sens choisis.'),
('L’additivité en dérivation',r'Au nœud de séparation, dans les sens du schéma, $I_G=I_1+I_2$. Les intensités des branches ne sont pas forcément égales : elles dépendent des dipôles. Pour vérifier, mesurer les trois valeurs sans modifier le fonctionnement du circuit. Comparer les sommes en tenant compte de la résolution de l’appareil et des variations de la source.','','')],
r'Un générateur fournit $I_G=0{,}45\unite A$ à deux branches. On mesure $I_1=180\unite{mA}=0{,}180\unite A$. Alors $I_2=I_G-I_1=0{,}45-0{,}180=0{,}270\unite A=270\unite{mA}$. Les unités sont harmonisées avant la soustraction.',
r'\textbf{Question.} Le courant diminue-t-il après une lampe ? Dans un circuit scolaire série, mesurer successivement l’intensité avant et après une lampe, en interrompant l’alimentation pour modifier le montage. Recommencer avec deux lampes et comparer. Ensuite, sous conduite du professeur, mesurer une branche principale et deux branches dérivées. \textbf{À rendre :} schémas, calibres, tableau des mesures, somme des branches et conclusion. L’ampèremètre n’est jamais branché directement en dérivation sur une source.',
['L’intensité se mesure en A, avec un ampèremètre en série.','1 A correspond à 1 000 mA.','L’intensité est identique en tout point d’une branche série en régime établi.','Au nœud, les intensités s’additionnent avec les sens fixés.','La lampe convertit de l’énergie ; elle ne consomme pas le courant.'],
r'Brancher un ampèremètre comme un voltmètre peut court-circuiter la source et détruire le fusible de l’appareil ; vérifier le schéma hors alimentation.',[
E('L’unité','Quelle unité et quel symbole pour l’intensité ?@@Quel instrument la mesure ?','L’ampère, A.@@L’ampèremètre, généralement une fonction du multimètre.'),
E('Le branchement','Un ampèremètre se place-t-il en série ou en dérivation ?@@Faut-il couper l’alimentation pour modifier le circuit ?','En série dans la branche étudiée.@@Oui, puis faire vérifier le montage selon les consignes.'),
E('Convertir',r'Convertir $250\unite{mA}$ en A.@@Convertir $0{,}08\unite A$ en mA.',r'$0{,}250\unite A$.@@$80\unite{mA}$.',calculs=[('250/1000',.25),('.08*1000',80)]),
E('Dans une série',r'Avant une lampe, $I=0{,}12\unite A$. Quelle intensité après, dans la même branche ?@@La lampe a-t-elle consommé une partie du courant ?',r'$0{,}12\unite A$ dans le modèle en régime établi.@@Non ; elle a converti de l’énergie.'),
E('Un nœud simple',r'Deux courants de $0{,}10$ et $0{,}20\unite A$ se réunissent. Quelle intensité sortante ?@@Quelle loi utiliser ?',r'$0{,}30\unite A$.@@L’additivité des intensités au nœud, avec les sens annoncés.',calculs=[('.1+.2',.3)]),
E('Une branche inconnue',r'$I_G=0{,}50\unite A$ et $I_1=0{,}18\unite A$. Calculer $I_2$.@@Vérifier la somme.',r'$I_2=0{,}50-0{,}18=0{,}32\unite A$.@@$0{,}18+0{,}32=0{,}50\unite A$.',calculs=[('.5-.18',.32)]),
E('Attention aux unités',r'$I_G=600\unite{mA}$ et $I_1=0{,}25\unite A$. Trouver $I_2$ en mA.@@Puis en A.',r'$I_1=250\unite{mA}$ ; $I_2=600-250=350\unite{mA}$.@@$0{,}350\unite A$.',calculs=[('600-.25*1000',350)]),
E('Choisir un calibre',r'On attend environ $150\unite{mA}$. Entre les calibres 20 mA, 200 mA et 10 A, lequel permet une mesure précise sans dépassement attendu, une fois le courant vérifié ?@@Pourquoi commencer prudemment ?',r'200 mA est adapté si les bornes, protections et conditions d’utilisation le permettent.@@La valeur réelle peut être plus élevée ; on commence selon la notice et les consignes, avec un calibre sûr.'),
E('Le signe négatif',r'Un multimètre affiche $-0{,}15\unite A$. Que peut-on dire du sens du courant par rapport au branchement choisi ?@@Quelle valeur de l’intensité dans ce modèle ?',r'Il circule dans le sens opposé à la convention positive du branchement.@@Sa valeur est $0{,}15\unite A$ ; on vérifie les connexions hors alimentation.'),
E('Deux branches identiques',r'Deux branches strictement identiques sont alimentées de la même façon et le courant principal vaut $0{,}40\unite A$. Quel courant par branche dans le modèle symétrique ?@@La division par deux vaut-elle pour toutes branches ?',r'$0{,}20\unite A$ par branche.@@Non : elle suppose des branches identiques et les mêmes conditions.',calculs=[('.4/2',.2)]),
E('Une expérience cohérente ?',r'On mesure $I_G=0{,}300\unite A$, $I_1=0{,}122\unite A$ et $I_2=0{,}176\unite A$. Calculer l’écart de bilan.@@Faut-il rejeter la loi immédiatement ?',r'$0{,}122+0{,}176=0{,}298\unite A$ ; l’écart vaut $0{,}002\unite A$.@@Non : comparer à la précision, aux variations de la source et aux conditions de mesure.',calculs=[('.122+.176',.298),('.300-.298',.002)]),
E('Un emplacement dangereux','Un élève branche un ampèremètre directement entre les deux bornes d’une pile. Pourquoi le montage est-il incorrect ?@@Quelle correction conceptuelle proposer ?','L’appareil de faible résistance peut court-circuiter la pile.@@Il faut l’insérer dans la branche dont on veut mesurer le courant, hors alimentation et avec un calibre adapté.'),
E('Une lampe supplémentaire','On ajoute une lampe en série et le courant passe de 0,20 à 0,12 A dans toute la boucle. Est-ce contraire à l’unicité ?@@Que compare la loi ?','Non : le circuit a été modifié et sa valeur de courant peut changer.@@La loi compare les intensités en différents points d’un même circuit en régime établi.'),
E('Une branche ouverte',r'Dans un circuit, $I_1=0{,}15\unite A$ et $I_2=0{,}10\unite A$. On ouvre la branche 2. Quelle relation subsiste ?@@Peut-on affirmer que $I_1$ reste exactement identique avec toute source réelle ?',r'Le courant de la branche 2 devient nul et $I_G=I_1$ pour la branche encore fermée.@@Non : cela dépend aussi du générateur ; le modèle idéal le permet, mais une source réelle peut varier.'),
E('Trois branches',r'Le courant principal vaut $0{,}80\unite A$ ; deux branches valent $220\unite{mA}$ et $0{,}35\unite A$. Calculer la troisième.@@Donner un contrôle rapide.',r'$I_3=0{,}80-0{,}220-0{,}35=0{,}230\unite A$.@@Les trois valeurs sont positives et leur somme vaut $0{,}80\unite A$.',calculs=[('.8-.22-.35',.23)])],
E('Trouver la mesure incohérente',r'Un relevé indique $I_G=0{,}40\unite A$, $I_1=260\unite{mA}$ et $I_2=0{,}24\unite A$. Vérifier le bilan.@@Si les deux branches sont fiables, quel courant principal attendre ?@@Proposer trois vérifications avant de conclure à une loi fausse.',r'$0{,}260+0{,}24=0{,}50\unite A$, ce qui diffère de $0{,}40\unite A$.@@$0{,}50\unite A$.@@Vérifier les unités et calibres, le placement des appareils, et la stabilité du générateur entre les mesures ; contrôler aussi l’existence d’autres branches.',calculs=[('.26+.24',.5)])))

CHAPITRES.append(C(15,'Mesurer la tension électrique','Peut-il y avoir une tension sans courant ?',
['Brancher un voltmètre aux bornes d’un dipôle.','Appliquer additivité en série et unicité en dérivation.','Distinguer tension, intensité et conditions de fonctionnement.'],['Nœuds, branches et unités d’intensité.'],[
('La tension entre deux points',r'Une tension électrique se définit entre deux points ou aux bornes d’un dipôle. Elle se note $U$ et s’exprime en volts (V). Une source peut présenter une tension entre ses bornes même quand le circuit est ouvert et que le courant extérieur est nul. Tension et intensité sont donc deux grandeurs différentes ; leurs appareils ne se branchent pas de la même manière.','c15-voltmetre','Le voltmètre est branché en dérivation aux bornes de la résistance ; l’ampèremètre, s’il existe, reste en série.'),
('Utiliser le voltmètre',r'Choisir la fonction tension continue, les bornes V et COM, et un calibre adapté. Relier les pointes aux deux points étudiés sans ouvrir la branche. Pour une lecture positive aux bornes d’un générateur continu, V est reliée à la borne positive et COM à la borne négative. Inverser les pointes inverse le signe de la tension mesurée. On n’utilise ici que des sources scolaires autorisées.','',''),
('En série : additionner',r'Pour deux récepteurs en série alimentés par un générateur, avec les polarités choisies de façon cohérente, $U_G=U_1+U_2$. Il s’agit de l’additivité des tensions dans la boucle simple étudiée. Les tensions des récepteurs ne sont pas nécessairement égales : elles dépendent de leurs caractéristiques. Diviser la tension du générateur par deux exige des hypothèses supplémentaires.','c15-lois','En série, les tensions des récepteurs s’additionnent. En dérivation sur les mêmes nœuds, elles sont égales avec la même polarité.'),
('En dérivation : comparer les mêmes points',r'Deux dipôles reliés aux mêmes deux nœuds ont la même tension avec la même orientation : $U_1=U_2=U_G$ dans le montage directement alimenté. Un fil idéal présente une tension nulle à ses bornes. Un interrupteur fermé est modélisé comme un fil ; ouvert dans une boucle simple, il peut supporter une tension non nulle. Les généralisations hors de cette configuration demandent d’examiner le circuit.','','')],
r'Un générateur fournit $6{,}0\unite V$ à deux lampes en série. Si $U_1=2{,}4\unite V$, alors $U_2=6{,}0-2{,}4=3{,}6\unite V$. Si les deux lampes étaient reliées directement en dérivation au générateur idéal de $6{,}0\unite V$, chaque tension serait $6{,}0\unite V$ : c’est un autre montage.',
r'\textbf{Question.} Comment la tension se répartit-elle ? Avec une source scolaire adaptée et deux dipôles autorisés, réaliser un montage série puis un montage en dérivation. Dessiner avant de mesurer. Relever $U_G$, $U_1$ et $U_2$ avec les mêmes conventions de polarité. Comparer la somme en série et les valeurs en dérivation. \textbf{À rendre :} points de connexion V-COM, unités, résultats et discussion de la précision. Les tensions domestiques sont étudiées uniquement sur document.',
['Une tension se mesure entre deux points, en volts.','Le voltmètre se branche en dérivation.','Une tension non nulle peut exister dans un circuit ouvert.','En série, les tensions des récepteurs s’additionnent dans la boucle simple.','En dérivation, mêmes deux nœuds signifie même tension orientée.'],
r'Ne pas affirmer « tension identique partout » : c’est l’intensité qui est identique dans une branche série. La tension concerne toujours deux points.',[
E('La bonne grandeur','Quelle grandeur se mesure en volts ?@@Avec quel appareil ?','La tension électrique.@@Un voltmètre, souvent une fonction du multimètre.'),
E('Deux connexions','Comment brancher un voltmètre pour mesurer la tension d’une lampe ?@@Faut-il ouvrir sa branche pour insérer le voltmètre ?','En dérivation aux deux bornes de la lampe.@@Non : on relie les pointes à ses deux bornes selon le protocole.'),
E('Un circuit ouvert','Une pile non reliée à une lampe peut-elle présenter une tension ?@@Le courant extérieur est-il alors nécessairement non nul ?','Oui, entre ses bornes.@@Non : sans trajet fermé extérieur, le courant permanent extérieur est nul dans le modèle.'),
E('Convertir',r'Convertir $2{,}5\unite V$ en mV.@@Convertir $600\unite{mV}$ en V.',r'$2\,500\unite{mV}$.@@$0{,}600\unite V$.',calculs=[('2.5*1000',2500),('600/1000',.6)]),
E('Une dérivation simple',r'Deux lampes sont reliées aux mêmes bornes d’une source de $4{,}5\unite V$. Quelles tensions ont-elles dans le modèle ?@@Faut-il partager 4,5 V en deux ?','Chaque lampe a une tension de 4,5 V avec la même polarité.@@Non : l’égalité des tensions en dérivation ne correspond pas à un partage par deux.'),
E('Compléter une somme',r'En série, $U_G=9\unite V$ et $U_1=4\unite V$. Calculer $U_2$.@@Vérifier le résultat.',r'$U_2=9-4=5\unite V$.@@$4+5=9\unite V$.',calculs=[('9-4',5)]),
E('Trois récepteurs',r'Une boucle série comporte des tensions de $1{,}2$, $2{,}0$ et $2{,}8\unite V$. Quelle tension de générateur correspond ?@@Quelle convention est supposée ?',r'$U_G=1{,}2+2{,}0+2{,}8=6{,}0\unite V$.@@Les récepteurs sont orientés de manière cohérente dans la boucle et les fils sont idéaux.',calculs=[('1.2+2+2.8',6)]),
E('Inverser les pointes',r'Le voltmètre affiche $+3{,}0\unite V$. Que lit-on en inversant V et COM sans changer le circuit ?@@La valeur absolue a-t-elle changé ?',r'$-3{,}0\unite V$.@@Non : le signe traduit la polarité de la mesure.'),
E('Un interrupteur idéal','Quelle tension modélise-t-on aux bornes d’un interrupteur fermé idéal ?@@Peut-il néanmoins être parcouru par un courant ?','Une tension nulle.@@Oui : une tension nulle sur un fil idéal n’impose pas un courant nul.'),
E('Même tension, autre courant','Deux lampes différentes sont en dérivation. Leurs tensions sont-elles égales ?@@Leurs intensités le sont-elles nécessairement ?','Oui si elles sont reliées aux mêmes deux nœuds avec la même polarité.@@Non : les intensités dépendent aussi des caractéristiques des lampes.'),
E('Deux lampes non identiques',r'En série sous $6\unite V$, on mesure $1{,}8$ et $4{,}2\unite V$. Est-ce cohérent ?@@Pourquoi une réponse de 3 V pour chacune n’était-elle pas imposée ?','Oui : 1,8 + 4,2 = 6 V.@@Le partage égal n’est pas une loi générale ; les lampes n’ont pas forcément les mêmes caractéristiques.',calculs=[('1.8+4.2',6)]),
E('Une mesure en trop ?',r'Un élève relie les deux pointes d’un voltmètre au même nœud et lit environ $0\unite V$. Est-ce surprenant ?@@Mesure-t-il la tension de la lampe située ailleurs ?','Non : les deux points appartiennent au même nœud idéal.@@Non : pour la lampe, il faut relier les pointes à ses deux bornes distinctes.'),
E('Un bilan mesuré',r'$U_G=6{,}02\unite V$, $U_1=2{,}51\unite V$, $U_2=3{,}49\unite V$. Comparer somme et source.@@Comment conclure sans excès ?',r'$U_1+U_2=6{,}00\unite V$, soit un écart de $0{,}02\unite V$.@@Comparer cet écart à la précision et à la stabilité des appareils ; les mesures peuvent être compatibles avec l’additivité.',calculs=[('2.51+3.49',6),('6.02-6',.02)]),
E('Une confusion dangereuse','Un élève veut mesurer la tension en mode ampèremètre, directement aux bornes d’une pile. Quel risque ?@@Que doit-il vérifier avant tout branchement ?','Il risque un court-circuit par l’appareil de faible résistance.@@Fonction tension continue, bornes V et COM, calibre adapté et schéma validé ; l’élève utilise seulement le matériel autorisé.'),
E('Retrouver le montage','Deux lampes ont chacune 6 V tandis que le générateur idéal fournit 6 V. Est-ce compatible avec une série simple de récepteurs aux tensions positives ?@@Quel montage est compatible ?','Non : en série, leur somme ferait 12 V.@@Une dérivation directe sur les deux bornes du générateur est compatible ; d’autres informations peuvent être nécessaires pour identifier tout le circuit.')],
E('Distinguer deux montages',r'Une source idéale de $9\unite V$ alimente deux récepteurs. En montage A, $U_1=3\unite V$ et $U_2=6\unite V$. En B, les deux valent 9 V. Proposer les associations.@@En A, peut-on déduire $I_1$ et $I_2$ séparément sans autre donnée ?@@En B, peut-on affirmer qu’ils sont égaux ?',r'A est compatible avec une série ; B avec une dérivation directe.@@La série impose $I_1=I_2$, mais pas leur valeur numérique sans caractéristique supplémentaire.@@Non : l’égalité des tensions ne suffit pas à imposer l’égalité des courants pour des dipôles différents.')))

CHAPITRES.append(C(16,'Résistance et loi d’Ohm','Peut-on prévoir le courant à partir d’une tension ?',
['Mesurer la caractéristique d’un conducteur ohmique.','Exploiter la relation U = R I avec les unités correctes.','Distinguer une loi de modèle d’une règle valable pour tous les dipôles.'],['Tension, intensité, proportionnalité et graphiques.'],[
('Caractériser un dipôle',r'Pour étudier une résistance, on mesure la tension $U$ à ses bornes et l’intensité $I$ qui la traverse pour plusieurs réglages autorisés de la source. Le voltmètre est en dérivation et l’ampèremètre en série. On ne dépasse pas les caractéristiques du composant, qui peut chauffer. Tracer $U$ en fonction de $I$ permet de rechercher une relation.','c16-montage','Le courant traverse A et R ; V compare les deux bornes de R. La source est réglable et limitée selon le matériel scolaire.'),
('Reconnaître un conducteur ohmique',r'À température suffisamment constante, la caractéristique d’un conducteur ohmique est une droite passant par l’origine. Le quotient $U/I$ est constant pour les points non nuls. Il définit la résistance $R$, en ohms ($\Omega$). Le nom « résistance » désigne à la fois un dipôle et une grandeur : le contexte doit être clair.','',''),
('Appliquer la loi d’Ohm',r'La loi s’écrit $U=RI$, avec $U$ en V, $R$ en $\Omega$ et $I$ en A. On en déduit $I=U/R$ ou $R=U/I$ lorsque les données le permettent. Convertir les milliampères en ampères avant de calculer. $1\unite{k\Omega}=1\,000\unite\Omega$. Une résistance plus élevée laisse passer un courant plus faible sous une même tension, dans ce modèle.','c16-ohm','La droite la plus pentue sur U en fonction de I correspond à la plus grande résistance.'),
('Connaître les limites',r'Tous les dipôles ne sont pas ohmiques. Une lampe à filament chauffe et sa caractéristique peut être courbe ; une diode dépend fortement de la polarité et de la tension. Pour mesurer un composant à l’ohmmètre, on le déconnecte de toute alimentation et on suit la notice. Une valeur expérimentale s’interprète avec tolérance et température, sans lui ajouter des décimales injustifiées.','','')],
r'Une résistance de $150\unite\Omega$ est soumise à $4{,}5\unite V$. Alors $I=U/R=4{,}5/150=0{,}030\unite A=30\unite{mA}$. Inversement, si $I=20\unite{mA}=0{,}020\unite A$, la tension vaut $U=150\times0{,}020=3{,}0\unite V$. On vérifie que le composant supporte le fonctionnement demandé.',
r'\textbf{Question.} Le dipôle fourni est-il compatible avec le modèle ohmique ? Réaliser le montage vérifié par le professeur. Mesurer au moins quatre couples $(I;U)$ dans la plage autorisée, sans échauffement excessif. Construire le graphique $U=f(I)$, puis calculer quelques quotients $U/I$. Comparer la régularité à la précision de mesure. \textbf{À rendre :} schéma, tableau en unités SI, graphique et conclusion limitée à la plage étudiée. L’ohmmètre ne s’utilise jamais sur un circuit alimenté.',
['La caractéristique relie tension et intensité dans des conditions précisées.','Un conducteur ohmique vérifie U = R I à température constante.','La résistance s’exprime en ohms.','Une droite passant par l’origine révèle une proportionnalité.','La loi d’Ohm ne décrit pas tous les dipôles.'],
r'Utiliser $I=30$ pour $30\unite{mA}$ donnerait un résultat mille fois trop grand avec des ohms : écrire d’abord $I=0{,}030\unite A$.',[
E('L’unité de R','Quelle est l’unité de résistance ?@@Quel symbole utilise-t-on ?',r'L’ohm.@@$\Omega$.'),
E('La relation','Écrire la loi d’Ohm.@@Donner les unités nécessaires.',r'$U=RI$.@@U en volts, R en ohms et I en ampères.'),
E('Convertir',r'Convertir $40\unite{mA}$ en A.@@Convertir $2{,}2\unite{k\Omega}$ en ohms.',r'$0{,}040\unite A$.@@$2\,200\unite\Omega$.',calculs=[('40/1000',.04),('2.2*1000',2200)]),
E('Une tension directe',r'R vaut $100\unite\Omega$ et I vaut $0{,}02\unite A$. Calculer U.@@Le produit est-il en volts ?',r'$U=100\times0{,}02=2\unite V$.@@Oui avec les unités de la loi.',calculs=[('100*.02',2)]),
E('Une droite','Quelle forme prend U en fonction de I pour un conducteur ohmique idéal ?@@Passe-t-elle par l’origine ?','Une droite.@@Oui : U est proportionnelle à I dans le domaine étudié.'),
E('Retrouver le courant',r'$U=6\unite V$ et $R=200\unite\Omega$. Calculer I en A puis mA.@@Vérifier avec U = R I.',r'$I=6/200=0{,}030\unite A=30\unite{mA}$.@@$200\times0{,}030=6\unite V$.',calculs=[('6/200',.03)]),
E('Retrouver R',r'$U=4{,}0\unite V$ pour $I=20\unite{mA}$. Trouver R.@@Pourquoi la réponse 0,2 ohm serait-elle incorrecte ?',r'$I=0{,}020\unite A$ ; $R=4{,}0/0{,}020=200\unite\Omega$.@@Elle provient de l’emploi de 20 au lieu de 0,020 pour une intensité en ampères.',calculs=[('4/.02',200)]),
E('Une table cohérente',r'On mesure $(I;U)$ : $(0{,}01;1{,}5)$, $(0{,}02;3)$, $(0{,}03;4{,}5)$, en A et V. Trouver R.@@Prévoir U pour 0,04 A.',r'Les quotients valent tous $150\unite\Omega$.@@$U=150\times0{,}04=6\unite V$, si le domaine et les caractéristiques du composant le permettent.',calculs=[('1.5/.01',150),('150*.04',6)]),
E('Comparer sous la même tension',r'Sous $6\unite V$, calculer I pour $100\unite\Omega$ puis $300\unite\Omega$.@@Quelle résistance laisse passer le plus grand courant ?',r'$0{,}060\unite A$ puis $0{,}020\unite A$.@@La plus faible résistance, $100\unite\Omega$, sous cette même tension.',calculs=[('6/100',.06),('6/300',.02)]),
E('Doubler U',r'Pour R constante, I vaut $15\unite{mA}$ sous $3\unite V$. Prévoir I sous $6\unite V$.@@Quelle hypothèse est essentielle ?',r'$30\unite{mA}$ : tension et intensité sont proportionnelles.@@Le dipôle reste ohmique avec la même résistance, notamment sans variation importante de température.'),
E('Une lampe courbe','La caractéristique d’une lampe ne forme pas une droite. Peut-on utiliser une seule valeur de R pour tous ses fonctionnements ?@@Quelle méthode reste possible ?','Non : le quotient U/I varie avec le point de fonctionnement.@@Lire ou mesurer le couple de valeurs au fonctionnement étudié, sans imposer une proportionnalité globale.'),
E('Un point suspect',r'Un dipôle de $100\unite\Omega$ donne $2\unite V$ pour $0{,}020\unite A$, mais un relevé indique $5\unite V$ pour $0{,}030\unite A$. Quelle valeur attend-on au second point ?@@Que vérifier ?',r'$U=100\times0{,}030=3\unite V$.@@La transcription, les calibres, les branchements et l’échauffement ; la donnée de 5 V est incompatible avec ce modèle constant.',calculs=[('100*.03',3)]),
E('L’ohmmètre','Pourquoi déconnecter toute alimentation avant une mesure à l’ohmmètre ?@@Pourquoi isoler si nécessaire la résistance des autres branches ?','L’appareil effectue sa propre mesure ; une tension extérieure perturbe le résultat et peut l’endommager.@@D’autres trajets électriques peuvent fausser la résistance mesurée par rapport au composant seul.'),
E('Une tolérance fournie',r'Une résistance annoncée $220\unite\Omega$ admet ici une plage de $209$ à $231\unite\Omega$. Une mesure de $225\unite\Omega$ est-elle compatible ?@@Sous $4{,}5\unite V$, calculer le courant avec la valeur mesurée.',r'Oui : $209\leq225\leq231$.@@$I=4{,}5/225=0{,}020\unite A=20\unite{mA}$.',calculs=[('4.5/225',.02)]),
E('Un choix raisonné',r'Une source scolaire de $6\unite V$ doit alimenter une résistance avec un courant ne dépassant pas $20\unite{mA}$. Quelle résistance minimale théorique ?@@Une résistance de 330 ohms convient-elle pour le courant, sous réserve de puissance admissible ?',r'$R\geq U/I=6/0{,}020=300\unite\Omega$.@@Oui : $I=6/330\approx18{,}2\unite{mA}$, inférieur à 20 mA. Il faut aussi vérifier la puissance et les tolérances.',calculs=[('6/.02',300),('6/330*1000',6/330*1000)])],
E('Identifier une boîte',r'Pour une boîte inconnue, on mesure 2 V à 10 mA, 4 V à 20 mA et 6 V à 30 mA. Estimer R et la nature du modèle.@@Prévoir le courant à 5 V.@@Pourquoi ne pas poursuivre automatiquement jusqu’à 100 V ?',r'Les quotients valent $200\unite\Omega$ : comportement compatible avec un conducteur ohmique dans la plage mesurée.@@$I=5/200=0{,}025\unite A=25\unite{mA}$.@@La conclusion ne vaut que dans le domaine étudié ; tension, puissance, échauffement et sécurité imposent des limites. L’élève reste sur le matériel scolaire autorisé.',calculs=[('2/.01',200),('5/200',.025)])))

CHAPITRES.append(C(17,'Puissance et énergie électrique','Une lampe puissante consomme-t-elle toujours plus ?',
['Distinguer puissance et énergie.','Calculer avec E = P t et des unités cohérentes.','Comparer des usages sur une durée et un service identifiés.'],['Proportionnalité, tension et intensité.'],[
('Un approfondissement de cycle',r'Les relations énergétiques sont des objectifs de fin de cycle. Ce chapitre propose une première maîtrise accompagnée en 4e ; le professeur peut en réserver une partie à la 3e. La puissance $P$ indique une énergie transférée par unité de durée. Son unité est le watt (W) : $1\unite W=1\unite{J/s}$. Une grande puissance n’implique pas une grande énergie totale si la durée est très courte.','c17-puissance','Une même énergie peut être transférée rapidement à forte puissance ou plus lentement à faible puissance.'),
('Relier énergie et durée',r'Pour une puissance constante, $E=P\Delta t$. Avec $P$ en W et $\Delta t$ en s, $E$ est en J. Avec $P$ en W et la durée en h, l’énergie est en Wh. $1\unite{Wh}=3\,600\unite J$ et $1\unite{kWh}=1\,000\unite{Wh}$. Ne pas écrire kW/h à la place de kWh : ce ne sont pas les mêmes grandeurs.','',''),
('Relier puissance, tension et intensité',r'En courant continu, pour un récepteur dans les conditions du modèle, la puissance électrique reçue vaut $P=UI$, avec U en V et I en A. Les indications nominales d’un appareil décrivent un fonctionnement prévu ; elles ne doivent pas être dépassées au hasard. Une résistance peut dissiper de l’énergie thermiquement et chauffer. La valeur maximale admissible du composant compte autant que sa résistance.','c17-energie','Le graphe E en fonction du temps est une droite pour chaque puissance constante ; sa pente dépend de P.'),
('Comparer des usages',r'Comparer une consommation demande la puissance et la durée d’utilisation, mais aussi un service rendu comparable. Un coût peut être estimé par $\text{énergie en kWh}\times\text{prix par kWh}$, si le prix est fourni ; les tarifs des exercices sont fictifs, pas des prix actuels. La veille, la fabrication et l’alimentation du numérique peuvent ajouter des dépenses hors du simple temps d’usage affiché.','','')],
r'Une lampe de $8\unite W$ fonctionne $3\unite h$. $E=8\times3=24\unite{Wh}=0{,}024\unite{kWh}$. En joules : $24\times3\,600=86\,400\unite J$. Avec le tarif fictif de $0{,}25$ euro par kWh, le coût d’énergie seul est $0{,}024\times0{,}25=0{,}006$ euro ; il ne représente pas le prix total d’un abonnement.',
r'\textbf{Mission documentaire.} Comparer deux éclairages assurant un service annoncé équivalent. Relever les puissances et fixer une même durée d’usage. Calculer les énergies en Wh puis kWh. Étudier un deuxième scénario où les durées diffèrent. \textbf{À rendre :} hypothèses, tableau de calcul, unités et conclusion. Si un matériel scolaire permet une mesure, le professeur choisit une alimentation protégée et un dispositif compatible ; aucun appareil domestique n’est démonté.',
['La puissance s’exprime en W et l’énergie en J, Wh ou kWh.','À puissance constante, E = P t.','Les unités du produit déterminent celles de l’énergie.','En courant continu, P = U I dans les conditions étudiées.','Une comparaison équitable précise durée et service rendu.'],
r'« 2 kW pendant une demi-heure font 4 kWh. » Il faut multiplier : $2\times0{,}5=1\unite{kWh}$.',[
E('Deux grandeurs','Une étiquette indique 10 W. S’agit-il d’une énergie ou d’une puissance ?@@Quelle unité conviendrait à une énergie ?','Une puissance.@@J, Wh ou kWh, selon le contexte.'),
E('Une heure',r'Une lampe de $5\unite W$ fonctionne $1\unite h$. Quelle énergie en Wh ?@@En joules ?',r'$5\unite{Wh}$.@@$5\times3\,600=18\,000\unite J$.',calculs=[('5*3600',18000)]),
E('Convertir',r'Convertir $1{,}5\unite{kWh}$ en Wh.@@Convertir $30\unite{min}$ en h.',r'$1\,500\unite{Wh}$.@@$0{,}5\unite h$.',calculs=[('1.5*1000',1500),('30/60',.5)]),
E('Un produit électrique',r'Un récepteur reçoit $6\unite V$ sous $0{,}20\unite A$. Calculer sa puissance.@@Donner l’unité.',r'$P=UI=6\times0{,}20=1{,}2\unite W$.@@Le watt.',calculs=[('6*.2',1.2)]),
E('La durée compte','A fonctionne à 20 W pendant 1 h ; B à 10 W pendant 1 h. Lequel reçoit le plus d’énergie ?@@L’égalité des durées est-elle utile ici ?','A : 20 Wh contre 10 Wh.@@Oui : à durée égale, l’énergie est proportionnelle à la puissance.'),
E('En secondes',r'Un moteur de $3\unite W$ fonctionne $40\unite s$. Calculer E.@@Pourquoi la réponse n’est-elle pas en Wh ?',r'$E=3\times40=120\unite J$.@@La durée est en secondes ; W multiplié par s donne J.',calculs=[('3*40',120)]),
E('Une demi-heure',r'Un appareil de $60\unite W$ fonctionne $30\unite{min}$. Calculer l’énergie en Wh et kWh.@@Calculer en J.',r'$E=60\times0{,}5=30\unite{Wh}=0{,}030\unite{kWh}$.@@$30\times3\,600=108\,000\unite J$.',calculs=[('60*.5',30),('30*3600',108000)]),
E('Retrouver une durée',r'Une source transfère $180\unite J$ à puissance constante de $6\unite W$. Quelle durée ?@@Vérifier.',r'$\Delta t=E/P=180/6=30\unite s$.@@$6\times30=180\unite J$.',calculs=[('180/6',30)]),
E('Une intensité nominale',r'Un moteur scolaire de $2{,}4\unite W$ fonctionne sous $6\unite V$ en courant continu. Calculer I dans ce modèle.@@Exprimer en mA.',r'$I=P/U=2{,}4/6=0{,}40\unite A$.@@$400\unite{mA}$.',calculs=[('2.4/6',.4)]),
E('Un coût fictif',r'Une énergie de $2{,}5\unite{kWh}$ est facturée au prix fictif de $0{,}20$ euro/kWh. Quel coût d’énergie ?@@Cela inclut-il forcément l’abonnement ?',r'$2{,}5\times0{,}20=0{,}50$ euro.@@Non : le calcul ne porte que sur le poste défini dans l’énoncé.',calculs=[('2.5*.2',.5)]),
E('Puissante mais brève',r'A reçoit $100\unite W$ pendant $1\unite{min}$ ; B $10\unite W$ pendant $20\unite{min}$. Comparer les énergies.@@Pourquoi la puissance seule ne suffit-elle pas ?',r'A : $100\times60=6\,000\unite J$ ; B : $10\times1\,200=12\,000\unite J$.@@B reçoit deux fois plus d’énergie malgré sa puissance plus faible, car sa durée est beaucoup plus longue.',calculs=[('100*60',6000),('10*20*60',12000)]),
E('Une veille',r'Un dispositif consomme $2\unite W$ en veille pendant $20\unite h$ par jour. Calculer l’énergie quotidienne puis pour 30 jours.@@Que manque-t-il pour l’énergie totale de l’appareil ?',r'$40\unite{Wh}$ par jour ; $1\,200\unite{Wh}=1{,}2\unite{kWh}$ pour 30 jours.@@Les autres périodes de fonctionnement et éventuellement les postes inclus dans un périmètre plus large.',calculs=[('2*20',40),('40*30',1200)]),
E('Une résistance qui chauffe',r'Une résistance de $100\unite\Omega$ est sous $5\unite V$. Trouver I puis P.@@Une puissance admissible de 0,125 W suffirait-elle ?',r'$I=5/100=0{,}050\unite A$ ; $P=5\times0{,}050=0{,}25\unite W$.@@Non : $0{,}25>0{,}125\unite W$. Le composant serait sollicité au-delà de sa valeur admissible.',calculs=[('5/100',.05),('5*.05',.25)]),
E('Même service',r'Pour un éclairage annoncé équivalent, A vaut 40 W et B 8 W. Calculer l’économie sur 100 h en kWh.@@Quelle limite ajouter à la conclusion ?',r'A : $4\unite{kWh}$ ; B : $0{,}8\unite{kWh}$ ; économie : $3{,}2\unite{kWh}$.@@Vérifier que qualité et quantité de lumière sont comparables ; ce calcul ne comprend pas tout le cycle de vie.',calculs=[('(40-8)*100/1000',3.2)]),
E('Une unité fausse','Une copie écrit « E = 2 kW/h après deux heures ». Identifier le problème.@@Donner le résultat pour une puissance de 2 kW pendant 2 h.',r'kW/h n’est pas une unité d’énergie ; il faut multiplier puissance et durée.@@$E=2\times2=4\unite{kWh}$.',calculs=[('2*2',4)])],
E('Le projet d’éclairage',r'Dix lampes de $12\unite W$ fonctionnent $4\unite h$ par jour pendant 20 jours. Calculer l’énergie totale.@@On les remplace par des lampes de 8 W assurant le même service. Calculer l’économie.@@À un prix fictif de 0,25 euro/kWh, quel gain sur le seul poste énergie ?',r'$E=10\times12\times4\times20=9\,600\unite{Wh}=9{,}6\unite{kWh}$.@@Nouvelle énergie : $6{,}4\unite{kWh}$ ; économie : $3{,}2\unite{kWh}$.@@$3{,}2\times0{,}25=0{,}80$ euro. Ce gain ne décide pas seul d’un achat : prix, durée de vie et impacts doivent être considérés.',calculs=[('10*12*4*20/1000',9.6),('10*8*4*20/1000',6.4),('3.2*.25',.8)])))
